def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data.get("roots", {})

    domains = {}
    for name in packages:
        forbidden = set(blocked.get(name, []))
        pin = pins.get(name)
        domains[name] = [None] + [row for row in packages[name]
                                  if row["version"] not in forbidden and
                                  (pin is None or row["version"] == pin)]

    best_vector = None
    best_versions = None
    domain_order = sorted(packages)

    for choices in product(*(domains[name] for name in domain_order)):
        selected = {name: row for name, row in zip(domain_order, choices)
                    if row is not None}
        versions = {name: row["version"] for name, row in selected.items()}
        if any(name not in versions or
               not bounds[0] <= versions[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        edges = {name: [] for name in selected}
        valid = True
        for name, row in selected.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if (target not in versions or
                        not dep["min"] <= versions[target] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for target in edges[name]:
                if not visit(target):
                    return False
            state[name] = 2
            return True

        if any(not visit(name) for name in edges):
            continue

        closure = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in closure:
                continue
            closure.add(name)
            stack.extend(edges[name])
        if closure != set(selected):
            continue

        vector = tuple(versions.get(name, -1) for name in names)
        if best_vector is None or vector > best_vector:
            best_vector, best_versions = vector, versions

    if best_vector is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _component_08(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    start_state = (source, initial_mask, 0)
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, 0)]
    coupons = data["coupons"]
    deadline = data["deadline"]

    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and used == coupons:
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            variants = [(edge["duration"], used)]
            if used < coupons:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                variants.append((duration, used + 1))
            next_node = edge["v"]
            next_mask = mask | bit_for.get(next_node, 0)
            for duration, next_used in variants:
                arrival = depart + duration
                if arrival > deadline:
                    continue
                next_state = (next_node, next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))

    return {"arrival": None}


